css:
.cocacap-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a211a;
    background: linear-gradient(165deg, #f5f0e6 0%, #eef2e6 55%, #e7efe2 100%);
    border-radius: 18px;
}

.cocacap-container * {
    box-sizing: border-box;
}

.cocacap-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #3d2b1f 0%, #5a4327 48%, #6b7a3a 100%);
    color: #f6f1e7;
    border-radius: 16px;
    margin-bottom: 16px;
    box-shadow: 0 14px 34px rgba(61, 43, 31, 0.32);
}

.cocacap-header h1 {
    margin: 10px 0 10px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.cocacap-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ecd9a8;
    background: rgba(236, 217, 168, 0.14);
    border: 1px solid rgba(236, 217, 168, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.cocacap-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6dcc7;
}

.cocacap-ticker {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px 16px;
    background: #2a211a;
    color: #f2e9d8;
    border-radius: 12px;
    padding: 12px 18px;
    margin-bottom: 16px;
    box-shadow: 0 8px 20px rgba(42, 33, 26, 0.24);
    font-variant-numeric: tabular-nums;
}

.cocacap-ticker-label,
.cocacap-ticker-budget {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #b9a78a;
}

.cocacap-ticker-value {
    font-size: 1.35rem;
    font-weight: 800;
    color: #f4c542;
}

.cocacap-ticker-move {
    font-size: 0.82rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: rgba(185, 167, 138, 0.18);
    color: #d9c9a6;
}

.cocacap-ticker-move.cocacap-move-up { color: #ff8a6b; background: rgba(255, 138, 107, 0.16); }
.cocacap-ticker-move.cocacap-move-down { color: #8fd694; background: rgba(143, 214, 148, 0.16); }

.cocacap-ticker-budget {
    margin-left: auto;
}

.cocacap-ticker-budget-value {
    font-size: 1.2rem;
    font-weight: 800;
    color: #9bd17e;
}

.cocacap-ticker-budget-value.cocacap-budget-low { color: #ff8a6b; }

.cocacap-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5d4f3f;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.cocacap-period-counter #currentDay,
.cocacap-period-counter #maxPeriods {
    font-weight: 800;
    color: #6b7a3a;
}

.cocacap-round-name {
    background: rgba(107, 122, 58, 0.16);
    color: #4f5e26;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cocacap-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a2b;
    background: rgba(138, 90, 43, 0.12);
    border: 1px solid rgba(138, 90, 43, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.cocacap-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cocacap-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(61, 43, 31, 0.08);
    border-top: 4px solid #6b7a3a;
}

.cocacap-card-cup { border-top-color: #6b7a3a; }
.cocacap-card-premium { border-top-color: #b8860b; }
.cocacap-card-retention { border-top-color: #5a4327; }
.cocacap-card-health { border-top-color: #2e8b8b; }

.cocacap-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a64;
}

.cocacap-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3d2b1f;
    font-variant-numeric: tabular-nums;
}

.cocacap-card-cup .cocacap-value { color: #5a6b2e; }
.cocacap-card-premium .cocacap-value { color: #a9790a; }
.cocacap-card-retention .cocacap-value { color: #5a4327; }
.cocacap-card-health .cocacap-value { color: #2e8b8b; }

.cocacap-sublabel {
    font-size: 0.76rem;
    color: #9a8a72;
    line-height: 1.35;
}

.cocacap-card-cup.cocacap-cup-specialty { border-top-color: #4caf50; }
.cocacap-card-cup.cocacap-cup-specialty .cocacap-value { color: #3f9a44; }
.cocacap-card-health.cocacap-health-danger { border-top-color: #d64545; }
.cocacap-card-health.cocacap-health-danger .cocacap-value { color: #d64545; }

.cocacap-meta-bars {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-bottom: 16px;
}

.cocacap-meta-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e4dcc9;
    color: #5d4f3f;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.cocacap-meta-label {
    font-size: 0.82rem;
    color: #8a7a64;
}

.cocacap-meta-bar #riskDisplay {
    font-size: 1.05rem;
    color: #d64545;
    font-weight: 800;
}

.cocacap-meta-bar.cocacap-risk-low #riskDisplay { color: #3f9a44; }
.cocacap-meta-bar.cocacap-risk-mid #riskDisplay { color: #b8860b; }

.cocacap-meta-bar #certDisplay {
    font-size: 0.95rem;
    color: #4f5e26;
    font-weight: 800;
    text-align: right;
}

.cocacap-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #6b7a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(61, 43, 31, 0.07);
}

.cocacap-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.cocacap-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #3d2b1f;
    margin-bottom: 6px;
}

.cocacap-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3d30;
}

.cocacap-briefing-text strong { color: #6b7a3a; }
.cocacap-briefing-text em { color: #a9790a; font-style: italic; }

.cocacap-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(61, 43, 31, 0.07);
}

.cocacap-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #3d2b1f;
    border-bottom: 2px solid #ece4d2;
    padding-bottom: 8px;
}

.cocacap-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a2f25;
    margin: 14px 0 6px;
}

.cocacap-container select {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc3ac;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2a211a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cocacap-container select:focus {
    outline: none;
    border-color: #6b7a3a;
    box-shadow: 0 0 0 3px rgba(107, 122, 58, 0.18);
}

.cocacap-container select option {
    background-color: #fffdf8;
    color: #2a211a;
}

.cocacap-container input,
.cocacap-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc3ac;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2a211a;
}

.cocacap-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cocacap-container .btn-primary {
    background: linear-gradient(135deg, #5a4327 0%, #6b7a3a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(90, 67, 39, 0.32);
}

.cocacap-container .btn-primary:hover {
    filter: brightness(1.08);
}

.cocacap-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #cdc3ac;
    color: #6d5e49;
    background: transparent;
}

.cocacap-coach {
    background: linear-gradient(160deg, #3d2b1f 0%, #4a3522 100%);
    color: #efe6d4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(61, 43, 31, 0.26);
}

.cocacap-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ecd9a8;
    margin-bottom: 8px;
}

.cocacap-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cocacap-coach-body strong { color: #cfe08a; }
.cocacap-coach-body em { color: #ecd9a8; font-style: italic; }

.cocacap-summit {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(61, 43, 31, 0.07);
    border-top: 4px solid #b8860b;
}

.cocacap-summit-header {
    font-size: 1.08rem;
    font-weight: 800;
    color: #3d2b1f;
    margin-bottom: 14px;
}

.cocacap-summit-buyers {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
}

.cocacap-summit-buyer {
    background: #f7f2e6;
    border: 1px solid #e4dcc9;
    border-radius: 12px;
    padding: 14px;
}

.cocacap-summit-name {
    font-weight: 800;
    font-size: 0.92rem;
    color: #5a4327;
    margin-bottom: 6px;
}

.cocacap-summit-need {
    font-size: 0.8rem;
    color: #8a7a64;
    line-height: 1.4;
    margin-bottom: 10px;
}

.cocacap-summit-result {
    font-weight: 800;
    font-size: 0.9rem;
    padding: 5px 12px;
    border-radius: 999px;
    display: inline-block;
    background: rgba(138, 122, 100, 0.16);
    color: #6d5e49;
}

.cocacap-summit-result.cocacap-contract-signed { background: rgba(76, 175, 80, 0.18); color: #3f9a44; }
.cocacap-summit-result.cocacap-contract-conditional { background: rgba(184, 134, 11, 0.18); color: #a9790a; }
.cocacap-summit-result.cocacap-contract-none { background: rgba(214, 69, 69, 0.16); color: #d64545; }

.cocacap-history,
.cocacap-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(61, 43, 31, 0.07);
}

.cocacap-history h3,
.cocacap-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #3d2b1f;
}

.cocacap-table-scroll {
    overflow-x: auto;
}

.cocacap-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3d30;
}

.cocacap-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #5a4327;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd2bd;
    white-space: nowrap;
}

.cocacap-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe9dc;
    color: #4a3d30;
}

.cocacap-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.cocacap-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cocacap-container {
        padding: 14px;
    }
    .cocacap-header h1 {
        font-size: 1.8rem;
    }
    .cocacap-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cocacap-value {
        font-size: 2.1rem;
    }
    .cocacap-meta-bars {
        grid-template-columns: 1fr;
    }
    .cocacap-summit-buyers {
        grid-template-columns: 1fr;
    }
    .cocacap-ticker-budget {
        margin-left: 0;
    }
    .cocacap-clock {
        margin-left: 0;
    }
    .cocacap-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

