(function() {
    'use strict';

    class FincaAlMundoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `De la Finca al Mundo`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` },
                { id: 5, titleKey: `briefing_title_r5`, textKey: `briefing_text_r5`, panelId: `round5Panel`, nameKey: `round_name_r5`, clockKey: `clock_r5` }
            ];

            // ---- Numbers reference card (COCACAP, Year 0 baseline). All USD. ----
            this.START_CUP = 79.2;        // SCA cup score (specialty threshold 80)
            this.START_PREMIUM = 35;      // % revenue above commodity spot (Fairtrade share)
            this.START_RETENTION = 87;    // % member families renewing
            this.START_HEALTH = 62;       // composite financial health 0–100
            this.START_UNHEDGED = 100;    // % of next harvest unhedged
            this.START_BUDGET = 220;      // $K Year-1 investment budget
            this.START_ICE = 1.80;        // ICE Coffee C price ($/lb)
            this.SPECIALTY = 80;          // SCA specialty grade
            this.BRAND_QUALITY_GATE = 82; // cup needed before a DTC brand is safe
            this.NORDIC_CUP = 85;         // Nordic Brews requires 85+ SCA

            // ---- ICE Coffee C price arc across the five cycles ($/lb). ----
            // R1 spike (Brazil squeeze), R2 collapse (large Brazilian harvest), recovery.
            this.ICE_ARC = [2.12, 1.65, 1.78, 1.88, 1.95];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cup: this.START_CUP,
                    premium: this.START_PREMIUM,
                    retention: this.START_RETENTION,
                    health: this.START_HEALTH,
                    unhedged: this.START_UNHEDGED,
                    budget: this.START_BUDGET,
                    ice: this.START_ICE,
                    iceMove: 0,

                    // capability state
                    qgrader: false,           // any cupping capability
                    cacaoFerment: false,      // fine-flavor cacao capability
                    traceability: false,      // plot-level GPS / EUDR ready
                    organicState: `none`,     // none | transition | certified
                    raCert: false,
                    stabFund: 0,              // reserve adequacy contribution (0–20)
                    buyerPipeline: false,     // direct-trade/specialty buyer relationship
                    cacaoBuyer: false,
                    dtcBrand: false,
                    differentialPay: false,   // cuadro de calidad in place
                    keyAccount: false,
                    ownExport: false,

                    // sticky run-defining flags (gate the top verdict, cap KPIs)
                    budgetBlown: false,       // spent the whole Year-1 budget, no buffer
                    unhedgedCollapse: false,  // hit the R2 collapse unhedged
                    strandedCerts: false,     // certified with no buyer to pay for it
                    failedShipment: false,    // chased buyers without the quality
                    eudrFail: false,          // no traceability -> lost the biggest buyer
                    brandErosion: false,      // brand before quality / free-rider erosion

                    // buyer summit outcomes
                    nordic: `pending`,
                    tablon: `pending`,
                    justa: `pending`,
                    allThree: false,

                    cupHistory: [this.START_CUP],
                    premiumHistory: [this.START_PREMIUM],
                    retentionHistory: [this.START_RETENTION],
                    healthHistory: [this.START_HEALTH],
                    iceHistory: [this.START_ICE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the five COMMON ERRORS — a blind
                // click-through must NOT win. (Over-invest with no hedge in R1;
                // chase certs/buyers without co-sequencing; ignore traceability;
                // launch the brand on uniform pricing.)
                state.decisions = {
                    wet: `full`,            // $140K — over-investing in Year 1
                    varietal: `full`,       // +$65K  -> blows the budget, no buffer
                    harvest: `none`,
                    hedge: `none`,          // no hedging -> devastated by the R2 collapse
                    qgrader: `none`,
                    ferment: `none`,
                    organic: `none`,
                    payment: `uniform`,     // uniform pricing -> free-rider erosion
                    outreach: `none`,
                    ra: `none`,
                    organicComplete: `delay`,
                    agro: `none`,
                    trace: `none`,          // ignore traceability -> EUDR failure
                    fund: `none`,
                    roaster: `chain`,       // chase the hardest buyer without the quality
                    cacao: `none`,
                    dtc: `full`,            // brand before quality consistency
                    export: `thirdparty`,
                    keyaccount: `none`,
                    contract: `spot`,
                    governance: `none`,
                    climate: `none`,
                    summit: `overpromise`
                };
            }
            this._updateBriefing(state);
        }

        // Cost lookups ($K) for the budget-exhaustion logic.
        _r1Cost(d) {
            const wet = { none: 0, repair: 35, central: 80, full: 140 }[d.wet] || 0;
            const varietal = { none: 0, graft: 28, full: 65 }[d.varietal] || 0;
            const harvest = { none: 0, sort: 8, selective: 22 }[d.harvest] || 0;
            // Hedging via forward contract has no upfront cost; futures need margin (~$6–10K).
            const hedge = { none: 0, futures30: 6, forward30: 0, futures50: 10 }[d.hedge] || 0;
            return wet + varietal + harvest + hedge;
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const read = (id, key) => { const el = document.getElementById(id); if (el) decisions[key] = el.value; };

            if (round === 1) {
                read(`wetInput`, `wet`);
                read(`varietalInput`, `varietal`);
                read(`harvestInput`, `harvest`);
                read(`hedgeInput`, `hedge`);
                const cost = this._r1Cost(decisions);
                if (!Number.isFinite(cost)) { warn(`warn_generic`); return false; }
                if (cost > this.START_BUDGET) { warn(`warn_overbudget`); return false; }
            } else if (round === 2) {
                read(`qgraderInput`, `qgrader`);
                read(`fermentInput`, `ferment`);
                read(`organicInput`, `organic`);
                read(`paymentInput`, `payment`);
                read(`outreachInput`, `outreach`);
                if (!decisions.qgrader) { warn(`warn_generic`); return false; }
            } else if (round === 3) {
                read(`raInput`, `ra`);
                read(`organicCompleteInput`, `organicComplete`);
                read(`agroInput`, `agro`);
                read(`traceInput`, `trace`);
                read(`fundInput`, `fund`);
                if (!decisions.trace) { warn(`warn_generic`); return false; }
            } else if (round === 4) {
                read(`roasterInput`, `roaster`);
                read(`cacaoInput`, `cacao`);
                read(`dtcInput`, `dtc`);
                read(`exportInput`, `export`);
                read(`keyaccountInput`, `keyaccount`);
                if (!decisions.roaster) { warn(`warn_generic`); return false; }
            } else if (round === 5) {
                read(`contractInput`, `contract`);
                read(`governanceInput`, `governance`);
                read(`climateInput`, `climate`);
                read(`summitInput`, `summit`);
                if (!decisions.summit) { warn(`warn_generic`); return false; }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let cupD = 0, premiumD = 0, retentionD = 0, healthD = 0, unhedgedD = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // Live commodity price for this cycle.
            const prevIce = ds.ice;
            ds.ice = this.ICE_ARC[Math.min(round - 1, this.ICE_ARC.length - 1)];
            ds.iceMove = Math.round((ds.ice - prevIce) * 100) / 100;

            if (round === 1) {
                // El Diagnóstico — foundation + hedging + budget discipline.
                const cost = this._r1Cost(d);
                ds.budget = Math.round((this.START_BUDGET - cost) * 10) / 10;

                switch (d.wet) {
                    case `full`: cupD += 2.2; healthD -= 4; break;
                    case `central`: cupD += 1.8; healthD -= 1; break;
                    case `repair`: cupD += 0.9; break;
                    case `none`: cupD -= 0.3; break;
                }
                switch (d.varietal) {
                    case `full`: cupD += 1.0; healthD -= 3; break; // yield dip in transition
                    case `graft`: cupD += 0.6; healthD -= 1; break;
                    case `none`: break;
                }
                switch (d.harvest) {
                    case `selective`: cupD += 1.1; retentionD += 1; break;
                    case `sort`: cupD += 0.6; break;
                    case `none`: cupD -= 0.2; break;
                }

                // Hedging sets price-risk exposure for the R2 collapse.
                switch (d.hedge) {
                    case `futures50`: unhedgedD -= 50; break;
                    case `forward30`: unhedgedD -= 30; retentionD += 1; healthD += 1; break; // deepens buyer relationship
                    case `futures30`: unhedgedD -= 30; break;
                    case `none`: coachKey = `coach_r1_nohedge`; break;
                }

                // COMMON ERROR 1: invest in everything, no crisis buffer.
                if (ds.budget < 12) {
                    ds.budgetBlown = true;
                    healthD -= 12;
                    coachKey = `coach_r1_blown`;
                } else if (d.wet !== `none` && d.harvest !== `none` && d.hedge !== `none` && ds.budget >= 12) {
                    coachKey = `coach_r1_balanced`;
                }

                summaryKey = ds.budgetBlown ? `sum_r1_blown` :
                             (d.hedge === `none` ? `sum_r1_unhedged` :
                             ((d.wet === `central` || d.wet === `full`) && d.hedge !== `none` ? `sum_r1_good` : `sum_r1_weak`));
            } else if (round === 2) {
                // La Calidad — quality system + the price COLLAPSE.
                // Q-grader capability.
                switch (d.qgrader) {
                    case `fulltime`: cupD += 2.0; ds.qgrader = true; break;
                    case `consultant`: cupD += 1.4; ds.qgrader = true; break;
                    case `course`: cupD += 0.9; ds.qgrader = true; break;
                    case `none`: coachKey = `coach_r2_noq`; break;
                }
                // Cacao fermentation — gate to bean-to-bar.
                switch (d.ferment) {
                    case `central`: ds.cacaoFerment = true; cupD += 0.3; break;
                    case `specialist`: ds.cacaoFerment = true; cupD += 0.5; healthD -= 1; break;
                    case `repair`: cupD += 0.1; break;
                    case `none`: break;
                }
                // Organic transition (3-year cost, premium later).
                switch (d.organic) {
                    case `start50`: ds.organicState = `transition`; healthD -= 4; break;
                    case `start20`: ds.organicState = `transition`; healthD -= 2; break;
                    case `none`: break;
                }
                // Cuadro de calidad — member quality payment (free-rider control).
                switch (d.payment) {
                    case `differential`: ds.differentialPay = true; cupD += 1.6; retentionD += 2; break;
                    case `tiered`: ds.differentialPay = true; cupD += 0.9; retentionD += 1; break;
                    case `uniform`: cupD -= 1.0; retentionD -= 2; coachKey = `coach_r2_uniform`; break; // free-rider erosion
                }
                // Direct-trade outreach builds the buyer pipeline.
                switch (d.outreach) {
                    case `expo`: ds.buyerPipeline = true; premiumD += 3; break;
                    case `broker`: ds.buyerPipeline = true; premiumD += 2; break;
                    case `none`: break;
                }

                // THE PRICE COLLAPSE — 22% drop. Unhedged cooperatives are devastated.
                // Stabilization fund does not exist yet in R2, so the buffer is the R1 budget.
                if (ds.unhedged >= 80) {
                    ds.unhedgedCollapse = true;
                    healthD -= 22;
                    retentionD -= 6;
                    premiumD -= 3;
                    coachKey = `coach_r2_collapse`;
                } else if (ds.unhedged <= 50) {
                    healthD += 4;
                    coachKey = (coachKey === `coach_default`) ? `coach_r2_hedged` : coachKey;
                } else {
                    healthD -= 8;
                    retentionD -= 2;
                }

                if (d.qgrader !== `none` && d.payment === `differential` && ds.buyerPipeline) coachKey = `coach_r2_system`;

                summaryKey = ds.unhedgedCollapse ? `sum_r2_collapse` :
                             (d.qgrader !== `none` && d.payment === `differential` ? `sum_r2_good` :
                             (d.payment === `uniform` ? `sum_r2_uniform` : `sum_r2_weak`));
            } else if (round === 3) {
                // La Certificación — certs, agroforestry, traceability, reserves.
                if (d.ra === `pursue`) { ds.raCert = true; healthD -= 2; }

                // Organic completion only real if a transition was started in R2.
                if (d.organicComplete === `complete`) {
                    if (ds.organicState === `transition`) { ds.organicState = `certified`; }
                    else { coachKey = `coach_r3_noorganic`; healthD -= 1; } // paid for a cert that isn't real
                }

                switch (d.agro) {
                    case `full60`: cupD += 0.4; retentionD += 1; healthD -= 3; break;
                    case `shade25`: cupD += 0.2; healthD -= 1; break;
                    case `none`: break;
                }

                // Traceability — the EUDR gate.
                switch (d.trace) {
                    case `digital`: ds.traceability = true; premiumD += 2; break;
                    case `lots`: break;
                    case `none`: coachKey = `coach_r3_notrace`; break;
                }

                // Stabilization fund.
                switch (d.fund) {
                    case `r20`: ds.stabFund = 20; healthD += 9; retentionD += 1; break;
                    case `r15`: ds.stabFund = 15; healthD += 6; break;
                    case `r8`: ds.stabFund = 8; healthD += 3; break;
                    case `none`: coachKey = (coachKey === `coach_default`) ? `coach_r3_nofund` : coachKey; break;
                }

                // COMMON ERROR 3 (one half): certified but no buyer relationship -> stranded certs.
                const hasCerts = ds.raCert || ds.organicState === `certified`;
                if (hasCerts && !ds.buyerPipeline) {
                    ds.strandedCerts = true;
                    premiumD -= 4;
                    coachKey = `coach_r3_stranded`;
                } else if (ds.traceability && (ds.raCert || ds.organicState === `certified`) && ds.buyerPipeline) {
                    coachKey = `coach_r3_sequenced`;
                }

                summaryKey = ds.strandedCerts ? `sum_r3_stranded` :
                             (ds.traceability && ds.stabFund >= 15 ? `sum_r3_good` :
                             (d.trace === `none` ? `sum_r3_notrace` : `sum_r3_weak`));
            } else if (round === 4) {
                // El Mercado — buyers, brand, export, key accounts. Co-sequencing pays off here.
                const specialtyReady = ds.cup >= this.SPECIALTY && ds.qgrader;

                switch (d.keyaccount) {
                    case `hire`: ds.keyAccount = true; premiumD += 2; healthD -= 1; break;
                    case `designate`: ds.keyAccount = true; premiumD += 1; break;
                    case `none`: break;
                }
                if (d.export === `own`) { ds.ownExport = true; healthD += 2; premiumD += 1; }

                // Specialty roaster relationships.
                let chasedRoaster = false;
                switch (d.roaster) {
                    case `chain`: chasedRoaster = true; ds.buyerPipeline = true; premiumD += 12; break;
                    case `two`: chasedRoaster = true; ds.buyerPipeline = true; premiumD += 10; break;
                    case `one`: chasedRoaster = true; ds.buyerPipeline = true; premiumD += 7; break;
                    case `none`: break;
                }

                // COMMON ERROR 3 (other half): buyers without quality -> failed first shipment.
                if (chasedRoaster && !specialtyReady) {
                    ds.failedShipment = true;
                    premiumD -= 14;       // the premium you booked evaporates
                    retentionD -= 4;
                    healthD -= 6;
                    coachKey = `coach_r4_shipment`;
                } else if (chasedRoaster && specialtyReady) {
                    coachKey = `coach_r4_landed`;
                }

                // Cacao bean-to-bar — only real with fermentation capability.
                switch (d.cacao) {
                    case `artisan`:
                        if (ds.cacaoFerment) { ds.cacaoBuyer = true; premiumD += 5; }
                        else { premiumD -= 2; coachKey = `coach_r4_cacaofail`; }
                        break;
                    case `manufacturer`:
                        if (ds.cacaoFerment) { ds.cacaoBuyer = true; premiumD += 3; }
                        else { premiumD -= 1; coachKey = `coach_r4_cacaofail`; }
                        break;
                    case `none`: break;
                }

                // COMMON ERROR 4: no traceability -> EUDR enforcement loses the biggest buyer.
                if (!ds.traceability) {
                    ds.eudrFail = true;
                    premiumD -= 8;
                    retentionD -= 1;
                    coachKey = `coach_r4_eudr`;
                }

                // COMMON ERROR 5: brand before quality consistency / uniform pricing -> erosion.
                let dtcLaunched = (d.dtc !== `none`);
                if (dtcLaunched) {
                    ds.dtcBrand = true;
                    const brandSafe = ds.cup >= this.BRAND_QUALITY_GATE && ds.differentialPay;
                    if (brandSafe) {
                        premiumD += { ecommerce: 4, tourism: 5, full: 8 }[d.dtc] || 0;
                        coachKey = (coachKey === `coach_default`) ? `coach_r4_brandgood` : coachKey;
                    } else {
                        ds.brandErosion = true;
                        premiumD -= 6;
                        retentionD -= 3;
                        coachKey = `coach_r4_brand`;
                    }
                }

                summaryKey = ds.failedShipment ? `sum_r4_shipment` :
                             ds.brandErosion ? `sum_r4_brand` :
                             ds.eudrFail ? `sum_r4_eudr` :
                             (specialtyReady && ds.buyerPipeline ? `sum_r4_good` : `sum_r4_weak`);
            } else if (round === 5) {
                // La Cosecha Estratégica + the Buyer Summit.
                switch (d.contract) {
                    case `two`: premiumD += 3; healthD += 4; unhedgedD -= 20; break;
                    case `one`: premiumD += 1; healthD += 2; unhedgedD -= 10; break;
                    case `spot`: healthD -= 2; break;
                }
                switch (d.governance) {
                    case `board`: retentionD += 2; healthD += 2; break;
                    case `foundation`: retentionD += 3; break;
                    case `none`: break;
                }
                switch (d.climate) {
                    case `full`: cupD += 0.3; retentionD += 1; healthD -= 2; break;
                    case `nursery`: cupD += 0.1; break;
                    case `none`: break;
                }

                // ---- Buyer Summit: can you actually FULFILL each buyer? ----
                const specialtyReady = ds.cup >= this.NORDIC_CUP && ds.qgrader && ds.traceability;
                const certForNordic = ds.raCert || ds.organicState === `certified`;
                const honest = d.summit === `honest`;
                const overpromise = d.summit === `overpromise`;

                // Nordic Brews — 85+ cup, traceability, certification, no failed history.
                if (specialtyReady && certForNordic && ds.buyerPipeline && !ds.failedShipment) {
                    ds.nordic = honest ? `signed` : (overpromise ? `conditional` : `conditional`);
                } else if (ds.cup >= this.SPECIALTY && ds.traceability && ds.buyerPipeline && !ds.eudrFail) {
                    ds.nordic = `conditional`;
                } else {
                    ds.nordic = `none`;
                }

                // Tablón de Cacao — fine-flavor fermentation capability + cacao buyer work.
                if (ds.cacaoFerment && ds.cacaoBuyer) {
                    ds.tablon = honest ? `signed` : `conditional`;
                } else if (ds.cacaoFerment) {
                    ds.tablon = `conditional`;
                } else {
                    ds.tablon = `none`;
                }

                // Cooperativa Justa — Fairtrade/Organic supply + governance/retention credibility.
                if (ds.organicState === `certified` && ds.retention >= 80) {
                    ds.justa = honest ? `signed` : `conditional`;
                } else if (ds.retention >= 78) {
                    ds.justa = `conditional`;
                } else {
                    ds.justa = `none`;
                }

                // Overpromising on capability you don't have backfires (lost credibility).
                if (overpromise) { retentionD -= 1; healthD -= 1; }
                if (d.summit === `hedgebets`) { premiumD -= 2; }

                ds.allThree = (ds.nordic === `signed` && ds.tablon === `signed` && ds.justa === `signed`);
                const signedCount = [ds.nordic, ds.tablon, ds.justa].filter((x) => x === `signed`).length;
                const anyContract = [ds.nordic, ds.tablon, ds.justa].some((x) => x === `signed` || x === `conditional`);

                if (ds.allThree) { premiumD += 10; healthD += 6; coachKey = `coach_r5_allthree`; }
                else if (signedCount >= 1) { premiumD += signedCount * 3; coachKey = `coach_r5_some`; }
                else if (anyContract) { coachKey = `coach_r5_conditional`; }
                else { premiumD -= 4; coachKey = `coach_r5_none`; }

                summaryKey = ds.allThree ? `sum_r5_allthree` :
                             (signedCount >= 1 ? `sum_r5_some` :
                             (anyContract ? `sum_r5_conditional` : `sum_r5_none`));
            }

            // ---- Apply deltas (clamped). ----
            ds.cup = Math.max(60, Math.min(92, Math.round((ds.cup + cupD) * 10) / 10));
            ds.premium = Math.max(0, Math.min(100, Math.round(ds.premium + premiumD)));
            ds.retention = Math.max(0, Math.min(100, Math.round(ds.retention + retentionD)));
            ds.health = Math.max(0, Math.min(100, Math.round(ds.health + healthD)));
            ds.unhedged = Math.max(0, Math.min(100, Math.round(ds.unhedged + unhedgedD)));

            // ---- Sticky CAPS: a run-defining error must NOT reach the top verdict. ----
            // Each cap survives later good rounds (it gates, it is not a soft delta).
            if (ds.budgetBlown) ds.health = Math.min(ds.health, 48);
            if (ds.unhedgedCollapse) ds.health = Math.min(ds.health, 45);
            if (ds.strandedCerts) ds.premium = Math.min(ds.premium, 44);
            if (ds.failedShipment) ds.premium = Math.min(ds.premium, 42);
            if (ds.eudrFail) ds.premium = Math.min(ds.premium, 47);
            if (ds.brandErosion) { ds.premium = Math.min(ds.premium, 50); ds.retention = Math.min(ds.retention, 82); }

            // Apply the 1.15× Buyer-Summit bonus to premium revenue (the modelled reward).
            if (round === 5 && ds.allThree && !ds.failedShipment && !ds.strandedCerts && !ds.eudrFail && !ds.brandErosion) {
                ds.premium = Math.min(100, Math.round(ds.premium * 1.15));
            }

            ds.cupHistory.push(ds.cup);
            ds.premiumHistory.push(ds.premium);
            ds.retentionHistory.push(ds.retention);
            ds.healthHistory.push(ds.health);
            ds.iceHistory.push(ds.ice);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // Reveal the Buyer Summit verdicts after the final cycle.
            if (round === 5) this._renderSummit(ds);

            // Advance the on-screen briefing + decision panel to the NEXT cycle.
            // The framework increments state.currentPeriod synchronously *after* this
            // method returns, so it is still `round` here; the next cycle is round + 1.
            // Done synchronously (no setTimeout) so the panel stays in lockstep with the
            // period counter. The prior 500ms timer fired *after* the increment and read
            // the already-advanced counter, jumping two panels at once and skipping the
            // Cycle 2 ("La Calidad") decision panel entirely.
            this._updateBriefing({ currentPeriod: round + 1 });

            return {
                period: state.currentPeriod,
                cup: ds.cup,
                cupDelta: Math.round(cupD * 10) / 10,
                premium: ds.premium,
                premiumDelta: Math.round(premiumD),
                retention: ds.retention,
                health: ds.health,
                unhedged: ds.unhedged,
                ice: ds.ice,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _renderSummit(ds) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const cls = { signed: `cocacap-contract-signed`, conditional: `cocacap-contract-conditional`, none: `cocacap-contract-none`, pending: `` };
            const label = { signed: t(`contract_signed`), conditional: t(`contract_conditional`), none: t(`contract_no`), pending: t(`buyer_pending`) };
            [[`buyerNordicResult`, ds.nordic], [`buyerTablonResult`, ds.tablon], [`buyerJustaResult`, ds.justa]].forEach(function(pair) {
                const el = document.getElementById(pair[0]);
                if (el) {
                    el.textContent = label[pair[1]] || label.pending;
                    el.className = `cocacap-summit-result ` + (cls[pair[1]] || ``);
                }
            });
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`cupDisplay`, `domainState.cup`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.cocacap-card-cup`);
                if (card) card.classList.toggle(`cocacap-cup-specialty`, n >= self.SPECIALTY);
                return self._fmtDec(n);
            });
            uiManager.bind(`premiumDisplay`, `domainState.premium`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`healthDisplay`, `domainState.health`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.cocacap-card-health`);
                if (card) card.classList.toggle(`cocacap-health-danger`, n < 45);
                return `${n}`;
            });

            uiManager.bind(`riskDisplay`, `domainState.unhedged`, (v) => {
                const n = Math.round(Number(v));
                const bar = document.querySelectorAll(`.cocacap-meta-bar`)[0];
                if (bar) {
                    bar.classList.toggle(`cocacap-risk-low`, n <= 40);
                    bar.classList.toggle(`cocacap-risk-mid`, n > 40 && n < 80);
                }
                return `${n}%`;
            });

            uiManager.bind(`certDisplay`, `domainState`, () => self._certLabel());

            uiManager.bind(`iceDisplay`, `domainState.ice`, (v) => `$${Number(v).toFixed(2)}/lb`);
            uiManager.bind(`iceMoveDisplay`, `domainState.iceMove`, (v) => {
                const n = Number(v);
                const el = document.getElementById(`iceMoveDisplay`);
                if (el) {
                    el.classList.toggle(`cocacap-move-up`, n > 0);
                    el.classList.toggle(`cocacap-move-down`, n < 0);
                }
                if (n > 0) return `▲ +$${n.toFixed(2)}`;
                if (n < 0) return `▼ -$${Math.abs(n).toFixed(2)}`;
                return window.mySimulation.t(`ticker_steady`);
            });

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const n = Number(v);
                const el = document.getElementById(`budgetDisplay`);
                if (el) el.classList.toggle(`cocacap-budget-low`, n < 12);
                return `$${Math.round(n)}K`;
            });
        }

        _fmtDec(v) {
            const sim = window.mySimulation; const lang = (sim && (sim.lang || sim.language)) || `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _certLabel() {
            const ds = window.mySimulation ? window.mySimulation.state.domainState : null;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!ds) return t(`cert_fairtrade`);
            const parts = [t(`cert_fairtrade_short`)];
            if (ds.organicState === `certified`) parts.push(t(`cert_organic_short`));
            else if (ds.organicState === `transition`) parts.push(t(`cert_organic_transition`));
            if (ds.raCert) parts.push(t(`cert_ra_short`));
            if (ds.traceability) parts.push(t(`cert_trace_short`));
            return parts.join(` · `);
        }

        getChartConfig() {
            return {
                cocacapChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Premium revenue (%)`,
                                data: [],
                                borderColor: `#b8860b`,
                                backgroundColor: `rgba(184,134,11,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#b8860b`,
                                yAxisID: `y`
                            },
                            {
                                label: `Member retention (%)`,
                                data: [],
                                borderColor: `#5a4327`,
                                backgroundColor: `rgba(90,67,39,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#5a4327`,
                                yAxisID: `y`
                            },
                            {
                                label: `Cup score (SCA, ×1 on right)`,
                                data: [],
                                borderColor: `#6b7a3a`,
                                backgroundColor: `rgba(107,122,58,0.10)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6b7a3a`,
                                yAxisID: `yCup`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#5d4f3f`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#9a8a72` }, grid: { color: `rgba(61,43,31,0.06)` },
                                title: { display: true, text: `% (premium / retention)`, color: `#9a8a72` }
                            },
                            yCup: {
                                position: `right`, min: 70, max: 92,
                                ticks: { color: `#6b7a3a` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `Cup score (SCA)`, color: `#6b7a3a` }
                            },
                            x: {
                                ticks: { color: `#9a8a72` }, grid: { color: `rgba(61,43,31,0.04)` },
                                title: { display: true, text: `Cycle`, color: `#9a8a72` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.premiumHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `Y` + i));
            return {
                cocacapChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.premiumHistory.map((v) => Math.round(v)) },
                        { data: ds.retentionHistory.map((v) => Math.round(v)) },
                        { data: ds.cupHistory.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const cup = Math.round(ds.cup * 10) / 10;
            const premium = Math.round(ds.premium);
            const retention = Math.round(ds.retention);
            const health = Math.round(ds.health);

            // Composite mirrors the concept's 5.5 scoring pillars.
            // Market Transformation 30 / Quality 25 / Financial 20 / Resilience 15 / Summit 10.
            const marketScore = Math.min(100, (premium / 60) * 100);                 // target 60%+
            const qualityScore = Math.min(100, Math.max(0, (cup - 76) / (88 - 76) * 100));
            const financialScore = health;
            const resilienceScore = Math.min(100, retention * 0.7 + (100 - ds.unhedged) * 0.3);
            const signedCount = [ds.nordic, ds.tablon, ds.justa].filter((x) => x === `signed`).length;
            const summitScore = signedCount * 33.3;

            let composite = Math.round(
                marketScore * 0.30 + qualityScore * 0.25 + financialScore * 0.20 +
                resilienceScore * 0.15 + summitScore * 0.10
            );
            if (ds.allThree) composite = Math.round(Math.min(100, composite * 1.15));

            const anyError = ds.budgetBlown || ds.unhedgedCollapse || ds.strandedCerts ||
                             ds.failedShipment || ds.eudrFail || ds.brandErosion;

            const escaped = premium >= 60 && cup >= this.SPECIALTY && retention >= 82 &&
                            health >= 55 && ds.allThree && !anyError;

            let performance = `Commodity Trap`;
            if (escaped && composite >= 78) performance = `Commodity Trap Escaped`;
            else if (premium >= 50 && cup >= this.SPECIALTY && signedCount >= 1 && !anyError) performance = `Specialty Foothold`;
            else if (ds.unhedgedCollapse || ds.budgetBlown) performance = `Financial Fragility`;
            else if (ds.strandedCerts || ds.eudrFail) performance = `Stranded Certifications`;
            else if (ds.failedShipment || ds.brandErosion) performance = `Quality–Market Mismatch`;
            else if (composite >= 55) performance = `Partial Transformation`;

            const insights = [];
            if (escaped) insights.push(window.mySimulation.t(`insight_escaped`));
            else insights.push(window.mySimulation.t(`insight_trapped`));
            if (ds.budgetBlown) insights.push(window.mySimulation.t(`insight_budget`));
            if (ds.unhedgedCollapse) insights.push(window.mySimulation.t(`insight_hedge`));
            if (ds.strandedCerts) insights.push(window.mySimulation.t(`insight_stranded`));
            if (ds.failedShipment) insights.push(window.mySimulation.t(`insight_shipment`));
            if (ds.eudrFail) insights.push(window.mySimulation.t(`insight_eudr`));
            if (ds.brandErosion) insights.push(window.mySimulation.t(`insight_brand`));
            if (ds.allThree) insights.push(window.mySimulation.t(`insight_summit`));
            else if (signedCount === 0) insights.push(window.mySimulation.t(`insight_nosummit`));
            if (cup < this.SPECIALTY) insights.push(window.mySimulation.t(`insight_quality`));

            return {
                cup: cup,
                premium: premium,
                retention: retention,
                health: health,
                unhedged: ds.unhedged,
                signedCount: signedCount,
                allThree: ds.allThree,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            const round = state.currentPeriod;
            if (ds.budgetBlown && round <= 2) return window.mySimulation.t(`hint_budget`);
            if (ds.unhedgedCollapse) return window.mySimulation.t(`hint_hedge`);
            if (ds.failedShipment) return window.mySimulation.t(`hint_shipment`);
            if (ds.eudrFail) return window.mySimulation.t(`hint_eudr`);
            if (ds.brandErosion) return window.mySimulation.t(`hint_brand`);
            if (ds.strandedCerts) return window.mySimulation.t(`hint_stranded`);
            if (round === 1 && ds.unhedged >= 80) return window.mySimulation.t(`hint_nohedge`);
            if (round === 2 && !ds.qgrader) return window.mySimulation.t(`hint_quality`);
            if (round >= 3 && !ds.traceability) return window.mySimulation.t(`hint_trace`);
            if (ds.cup >= this.SPECIALTY && ds.premium >= 50 && ds.health >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Cycle`, i18nKey: `col_cycle` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.cup`, label: `Cup`, i18nKey: `col_cup`, formatter: (v) => self._fmtDec(Number(v)) },
                { key: `results.premium`, label: `Premium`, i18nKey: `col_premium`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.retention`, label: `Retention`, i18nKey: `col_retention`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.health`, label: `Health`, i18nKey: `col_health`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.ice`, label: `ICE C`, i18nKey: `col_ice`, formatter: (v) => `$${Number(v).toFixed(2)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

