    document.addEventListener(`DOMContentLoaded`, () => {
        const adapter = new FincaAlMundoAdapter();
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(adapter, {
            simulationType: `finca_al_mundo`,
            maxPeriods: 5,
            autoSaveInterval: 30000
        });

        // Keep the sim-owned briefing + decision panel in lockstep with the framework
        // in two cases the host player does not cover: (a) UNDO — the player's undo()
        // restores domainState and the period counter but never re-renders our panels;
        // (b) a mid-game LANGUAGE switch — applyTranslations() re-applies the static
        // data-i18n="briefing_title_r1" (snapping the title back to Cycle 1) and leaves
        // the non-i18n briefing body / round-name / clock stale in the previous language.
        const resync = () => { try { adapter._updateBriefing(window.mySimulation.state); } catch (e) {} };
        const undoBtn = document.getElementById(`undoBtn`);
        if (undoBtn) undoBtn.addEventListener(`click`, () => setTimeout(resync, 0));
        if (typeof window.mySimulation.setLang === `function`) {
            const _setLang = window.mySimulation.setLang.bind(window.mySimulation);
            window.mySimulation.setLang = function (lang) { _setLang(lang); resync(); };
        }
    });

})();
